// Plan the RBIS steps: the fixed list of adapter calls for this case's update path,
// minus the calls already recorded in stepsDone. One item per call still to make.
const ctx = $('Case details').first().json;
const input = $input.first().json;
const c = ctx.case;
const s = ctx.settings;
const norm = (x) => String(x ?? '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const done = Array.isArray(input.stepsDone) ? input.stepsDone : [];

// The people this row puts on the account: its own person, then (lead rows) each joint tenant.
const clean = (p) => ({ name: String(p.name ?? '').trim(), email: String(p.email ?? '').trim(), phone: String(p.phone ?? '').trim() });
const lead = clean({ name: c.tenantName, email: c.contactEmail, phone: c.contactPhone });
const joint = s.jointTenantHandling === 'referLaterRows' ? [] : (Array.isArray(ctx.jointTenants) ? ctx.jointTenants : []).map(clean);
const people = [lead, ...joint];
const withContacts = people.filter((p) => p.email || p.phone);

// Which path. A resumed move-in that never ended the landlord's liability was adding a person to an existing tenancy.
let path = input.planMode === 'addPerson' ? 'addPerson' : ctx.kind;
if (input.planMode === 'resume' && ctx.kind === 'moveIn' && !done.includes('endLiability')) path = 'addPerson';
if (!['moveIn', 'moveOut', 'addPerson'].includes(path)) {
  throw new Error(`No update path for change reason "${c.changeReason}"`);
}

// Who RBIS will end: the pretend RBIS ends every current liability, so name them all.
const current = Array.isArray(input.account?.current) ? input.account.current.map((x) => x.party) : null;

const steps = [];
const addTenants = () => people.forEach((p) => steps.push({
  stepId: `addLiableParty:${norm(p.name)}`, operation: 'addLiableParty', params: { name: p.name, type: 'tenant', startDate: c.startDate },
}));
const createDetail = () => steps.push({
  stepId: 'createDetail', operation: 'createDetail', params: { startDate: c.startDate, tenants: people.map((p) => p.name) },
});
const setContacts = () => withContacts.forEach((p) => steps.push({
  stepId: `setContactDetails:${norm(p.name)}`, operation: 'setContactDetails', params: { name: p.name, email: p.email, phone: p.phone },
}));

let outcome;
let followUpReason = '';
if (path === 'moveIn' || path === 'addPerson') {
  if (path === 'moveIn') {
    steps.push({ stepId: 'endLiability', operation: 'endLiability', params: { endDate: ctx.landlordEndDate, parties: current ?? (s.landlordNames ?? []) } });
  }
  addTenants();
  createDetail();
  setContacts();
  outcome = 'liability started';
  if (withContacts.length === 0) followUpReason = 'NO_CONTACT_DETAILS';
} else {
  const landlord = (s.landlordNames ?? [])[0];
  if (!landlord) throw new Error('settings.landlordNames is empty, so the landlord cannot be made liable again');
  const forwardingAddress = String(c.forwardingAddress ?? '').trim();
  steps.push({ stepId: 'endLiability', operation: 'endLiability', params: { endDate: c.endDate, parties: current ?? people.map((p) => p.name) } });
  steps.push({ stepId: `addLiableParty:${norm(landlord)}`, operation: 'addLiableParty', params: { name: landlord, type: 'landlord', startDate: ctx.landlordStartDate } });
  if (forwardingAddress) steps.push({ stepId: 'setForwardingAddress', operation: 'setForwardingAddress', params: { address: forwardingAddress } });
  outcome = forwardingAddress ? 'liability ended, address saved' : 'liability ended';
}

const remaining = steps.filter((st) => !done.includes(st.stepId));
const base = {
  caseId: ctx.caseId, rbisBaseUrl: s.rbisBaseUrl, ref: c.accountRef, path, outcome, followUpReason,
  stepsPlanned: steps.map((st) => st.stepId),
};
if (remaining.length === 0) return [{ json: { ...base, nothingLeft: true } }];

let soFar = [...done];
return remaining.map((st) => {
  const stepsDoneBefore = soFar;
  soFar = [...soFar, st.stepId];
  return { json: { ...base, nothingLeft: false, ...st, stepsDoneBefore, stepsDoneAfter: soFar } };
});
